type Ledger struct {
	db *sql.DB
}

func NewLedger(dataDir string) *Ledger {
	db, err := sql.Open("sqlite3", filepath.Join(dataDir, "ledger.db")+"?_journal_mode=WAL&_synchronous=FULL&_busy_timeout=5000")
	if err != nil {
		panic(err)
	}
	// A single connection avoids SQLITE_BUSY and makes it easy to reason about
	// the order of writes while still using WAL for crash durability.
	db.SetMaxOpenConns(1)

	_, err = db.Exec(`CREATE TABLE IF NOT EXISTS transactions (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		key TEXT NOT NULL UNIQUE,
		account TEXT NOT NULL,
		amount INTEGER NOT NULL,
		status TEXT NOT NULL DEFAULT 'pending'
	)`)
	if err != nil {
		panic(err)
	}
	_, err = db.Exec(`CREATE TABLE IF NOT EXISTS accounts (
		name TEXT PRIMARY KEY,
		balance INTEGER NOT NULL DEFAULT 0
	)`)
	if err != nil {
		panic(err)
	}
	// Databases created by older versions did not have the UNIQUE constraint.
	// The index provides the same durable guarantee for them. Duplicate keys
	// are not valid ledger state, so refuse to start if one is present.
	_, err = db.Exec(`CREATE UNIQUE INDEX IF NOT EXISTS transactions_key ON transactions(key)`)
	if err != nil {
		panic(err)
	}
	return &Ledger{db: db}
}

func (l *Ledger) Recover() {
	rows, err := l.db.Query("SELECT id FROM transactions WHERE status = 'pending' ORDER BY id")
	if err != nil {
		return
	}
	var ids []int64
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err == nil {
			ids = append(ids, id)
		}
	}
	rows.Close()

	for _, id := range ids {
		l.processOne(TxRequest{ID: id, Done: nil})
	}
}

func (l *Ledger) CreatePending(key, account string, amount int) int64 {
	res, err := l.db.Exec("INSERT INTO transactions(key, account, amount, status) VALUES(?, ?, ?, 'pending')", key, account, amount)
	if err != nil {
		panic(err)
	}
	id, err := res.LastInsertId()
	if err != nil {
		panic(err)
	}
	return id
}

func (l *Ledger) ProcessLoop(ch <-chan TxRequest) {
	for req := range ch {
		l.processOne(req)
	}
}

// processOne applies a transaction atomically. Concurrent callers processing
// the same ID are serialized by SQLite; only the first observes pending status.
func (l *Ledger) processOne(req TxRequest) {
	tx, err := l.db.Begin()
	if err != nil {
		panic(err)
	}

	var status string
	err = tx.QueryRow("SELECT status FROM transactions WHERE id = ?", req.ID).Scan(&status)
	if err != nil || status != "pending" {
		_ = tx.Rollback()
		if req.Done != nil {
			req.Done <- struct{}{}
		}
		return
	}

	_, err = tx.Exec("INSERT INTO accounts(name, balance) VALUES(?, -?) ON CONFLICT(name) DO UPDATE SET balance = balance - ?", req.Account, req.Amount, req.Amount)
	if err != nil {
		_ = tx.Rollback()
		panic(err)
