	_, err = tx.Exec("UPDATE transactions SET status = 'completed' WHERE id = ?", req.ID)
	if err != nil {
		_ = tx.Rollback()
		panic(err)
	}
	if err := tx.Commit(); err != nil {
		panic(err)
	}
	if req.Done != nil {
		req.Done <- struct{}{}
	}
}

