func (h *Handler) CreateTx(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	var req struct {
		Key     string `json:"key"`
		Account string `json:"account"`
		Amount  int    `json:"amount"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	// If this key is already completed, the durable lookup is authoritative and
	// no balance mutation is attempted. For a newly inserted pending row (or a
	// concurrently seen pending row), this atomic operation either applies it
	// exactly once or observes the winner's completed state.
	tx := h.ledger.GetTransaction(req.Key)
	if tx != nil && tx.Status == "completed" {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]interface{}{"key": req.Key, "status": tx.Status})
		return
	}

	id := h.ledger.CreatePending(req.Key, req.Account, req.Amount)
	done := make(chan struct{})
	h.ledger.processOne(TxRequest{ID: id, Done: done})
	<-done

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(map[string]interface{}{"key": req.Key, "status": "completed"})
}

